'use client';
import {useEffect,useMemo,useState} from 'react';
import VendorShell from '../../components/VendorShell';
import {api,post,patch} from '../../lib/api';
const naira=(k:number)=>`₦${(Number(k||0)/100).toLocaleString('en-NG',{minimumFractionDigits:2,maximumFractionDigits:2})}`;
const empty={code:'',name:'',type:'PERCENTAGE',value:'',minOrderAmount:'',maxDiscount:'',usageLimit:'',perCustomerLimit:'',startsAt:'',endsAt:''};
function status(p:any){const n=Date.now(),s=new Date(p.startsAt).getTime(),e=new Date(p.endsAt).getTime();return !p.isActive?'Inactive':n<s?'Scheduled':n>e?'Expired':'Live';}
export default function PromotionsPage(){
 const [rows,setRows]=useState<any[]>([]),[loading,setLoading]=useState(true),[error,setError]=useState(''),[saved,setSaved]=useState(''),[query,setQuery]=useState(''),[filter,setFilter]=useState('ALL');
 const [modal,setModal]=useState(false),[selected,setSelected]=useState<any>(null),[form,setForm]=useState<any>(empty),[saving,setSaving]=useState(false);
 const load=()=>{setLoading(true);api('/api/vendor/promotions').then(setRows).catch(e=>setError(e.message)).finally(()=>setLoading(false))}; useEffect(load,[]);
 const filtered=useMemo(()=>rows.filter(p=>{const q=query.toLowerCase();const match=!q||p.code.toLowerCase().includes(q)||p.name.toLowerCase().includes(q);const st=status(p);return match&&(filter==='ALL'||st.toUpperCase()===filter)}),[rows,query,filter]);
 const set=(k:string,v:any)=>setForm((f:any)=>({...f,[k]:v}));
 const openNew=()=>{setSelected(null);setForm({...empty,startsAt:new Date(Date.now()+60000).toISOString().slice(0,16),endsAt:new Date(Date.now()+7*86400000).toISOString().slice(0,16)});setModal(true)};
 const edit=(p:any)=>{setSelected(p);setForm({code:p.code,name:p.name,type:p.type,value:p.value,minOrderAmount:p.minOrderAmount/100,maxDiscount:p.maxDiscount==null?'':p.maxDiscount/100,usageLimit:p.usageLimit??'',perCustomerLimit:p.perCustomerLimit??'',startsAt:new Date(p.startsAt).toISOString().slice(0,16),endsAt:new Date(p.endsAt).toISOString().slice(0,16)});setModal(true)};
 async function save(){setSaving(true);setError('');try{const payload={name:form.name,type:form.type,value:Number(form.value),minOrderAmount:Math.round(Number(form.minOrderAmount||0)*100),maxDiscount:form.maxDiscount===''?undefined:Math.round(Number(form.maxDiscount)*100),usageLimit:form.usageLimit===''?undefined:Number(form.usageLimit),perCustomerLimit:form.perCustomerLimit===''?undefined:Number(form.perCustomerLimit),startsAt:new Date(form.startsAt).toISOString(),endsAt:new Date(form.endsAt).toISOString(),code:form.code};if(selected)await patch(`/api/vendor/promotions/${selected.id}`,payload);else await post('/api/vendor/promotions',payload);setModal(false);setSaved(selected?'Promotion updated':'Promotion created');load();setTimeout(()=>setSaved(''),2200)}catch(e:any){setError(e.message)}finally{setSaving(false)}}
 async function deactivate(p:any){if(!confirm(`Deactivate ${p.code}?`))return;try{await post(`/api/vendor/promotions/${p.id}/deactivate`);setSaved('Promotion deactivated');load();setTimeout(()=>setSaved(''),2200)}catch(e:any){setError(e.message)}}
 return <VendorShell><div className="promotion-page"><div className="page-heading-row"><div><span className="eyebrow">Sales tools</span><h1>Promotions</h1><p className="page-subtitle">Create discounts and campaign codes that help your store convert more orders.</p></div><button className="btn" onClick={openNew}>＋ Create promotion</button></div>
 {error&&<div className="error">{error}</div>}{saved&&<div className="success">{saved}</div>}
 <div className="promotion-metrics"><div><span>Total campaigns</span><strong>{rows.length}</strong></div><div><span>Live</span><strong>{rows.filter(p=>status(p)==='Live').length}</strong></div><div><span>Scheduled</span><strong>{rows.filter(p=>status(p)==='Scheduled').length}</strong></div><div><span>Uses</span><strong>{rows.reduce((a,p)=>a+(p.usageCount||0),0)}</strong></div></div>
 <div className="promotion-toolbar"><input className="input" placeholder="Search code or promotion…" value={query} onChange={e=>setQuery(e.target.value)}/><select className="input" value={filter} onChange={e=>setFilter(e.target.value)}><option value="ALL">All statuses</option><option value="LIVE">Live</option><option value="SCHEDULED">Scheduled</option><option value="EXPIRED">Expired</option><option value="INACTIVE">Inactive</option></select></div>
 {loading?<div className="card promotion-state">Loading promotions…</div>:!filtered.length?<div className="card promotion-state"><div className="state-icon">◇</div><h3>{query?'No promotions found':'Create your first promotion'}</h3><p>{query?'Try another search.':'Offer percentage or fixed discounts with limits and scheduling.'}</p>{!query&&<button className="btn" onClick={openNew}>Create promotion</button>}</div>:<div className="promotion-list">{filtered.map(p=><article className="promotion-card" key={p.id}><div className="promotion-top"><div className="promo-code">{p.code}</div><span className={`status-badge ${status(p)==='Live'?'status-active':status(p)==='Scheduled'?'status-warning':'status-muted'}`}>{status(p)}</span></div><h3>{p.name}</h3><div className="promo-value">{p.type==='PERCENTAGE'?`${p.value}% off`:`${naira(p.value)} off`}</div><div className="promo-details"><span>Min. order <b>{naira(p.minOrderAmount)}</b></span><span>Max discount <b>{p.maxDiscount==null?'No cap':naira(p.maxDiscount)}</b></span><span>Usage <b>{p.usageCount}{p.usageLimit!=null?` / ${p.usageLimit}`:' / unlimited'}</b></span><span>Per customer <b>{p.perCustomerLimit??'Unlimited'}</b></span></div><div className="promo-dates"><span>Starts {new Date(p.startsAt).toLocaleString()}</span><span>Ends {new Date(p.endsAt).toLocaleString()}</span></div><div className="promo-actions"><button onClick={()=>edit(p)}>Edit</button>{p.isActive&&<button onClick={()=>deactivate(p)}>Deactivate</button>}</div></article>)}</div>}
 {modal&&<div className="modal-backdrop"><div className="modal promotion-modal"><div className="modal-head"><div><span className="eyebrow">{selected?'Edit promotion':'New promotion'}</span><h2>{selected?'Update promotion':'Create promotion'}</h2></div><button onClick={()=>setModal(false)}>×</button></div><div className="form-grid"><label>Promotion name<input className="input" value={form.name} onChange={e=>set('name',e.target.value)} placeholder="Weekend savings"/></label><label>Code<input className="input" value={form.code} onChange={e=>set('code',e.target.value.toUpperCase())} disabled={!!selected} placeholder="WEEKEND20"/></label><label>Discount type<select className="input" value={form.type} onChange={e=>set('type',e.target.value)} disabled={!!selected}><option value="PERCENTAGE">Percentage</option><option value="FIXED_AMOUNT">Fixed amount</option></select></label><label>{form.type==='PERCENTAGE'?'Discount (%)':'Discount amount (₦)'}<input className="input" type="number" min="1" value={form.value} onChange={e=>set('value',e.target.value)}/></label><label>Minimum order (₦)<input className="input" type="number" min="0" value={form.minOrderAmount} onChange={e=>set('minOrderAmount',e.target.value)}/></label><label>Maximum discount (₦) <span className="field-optional">optional</span><input className="input" type="number" min="0" value={form.maxDiscount} onChange={e=>set('maxDiscount',e.target.value)}/></label><label>Usage limit <span className="field-optional">optional</span><input className="input" type="number" min="1" value={form.usageLimit} onChange={e=>set('usageLimit',e.target.value)}/></label><label>Per-customer limit <span className="field-optional">optional</span><input className="input" type="number" min="1" value={form.perCustomerLimit} onChange={e=>set('perCustomerLimit',e.target.value)}/></label><label>Starts<input className="input" type="datetime-local" value={form.startsAt} onChange={e=>set('startsAt',e.target.value)}/></label><label>Ends<input className="input" type="datetime-local" value={form.endsAt} onChange={e=>set('endsAt',e.target.value)}/></label></div><div className="modal-note"><b>How ROZZI applies it</b><p>Vendor promotions apply to this store's orders. Global platform promotions can still be managed separately by ROZZI administrators.</p></div><div className="modal-actions"><button className="btn secondary" onClick={()=>setModal(false)}>Cancel</button><button className="btn" disabled={saving||!form.name.trim()||!form.code.trim()||!form.value||!form.startsAt||!form.endsAt} onClick={save}>{saving?'Saving…':selected?'Save changes':'Create promotion'}</button></div></div></div>}
 </div></VendorShell>
}
